(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  let wy = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  wx += Math.sin((x+y)*0.01+t*0.5)*8+Math.cos((x-y)*0.012-t*0.4)*6;
  wy += Math.cos((x-y)*0.01-t*0.45)*8+Math.sin((x+y)*0.013+t*0.38)*6;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.3+1)*60, 0.11, 2.1],
    [400+Math.cos(t*0.45+2)*80, 200+Math.sin(t*0.65+4)*50, 0.085, 1.8],
    [200+Math.sin(t*0.55+6)*110, 220+Math.cos(t*0.75)*70, 0.095, 2.4],
    [300+Math.cos(t*0.25+1)*130, 30+Math.sin(t*0.85+2)*80, 0.075, 2.0]
  ];
  let aS=0, iS=0, cross=0;
  for (let j=0; j<src.length; j++) {
    const [sX,sY,f,sp]=src[j];
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a=Math.sin(d*f-t*sp), i=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS+=a; iS+=i;
    for (let k=j+1;k<src.length;k++){
      const [sX2,sY2]=src[k];
      const d2=Math.sqrt((sx-sX2)**2+(sy-sY2)**2);
      cross+=Math.sin(d*f+d2*src[k][2]*0.5-t*(sp+src[k][3])*0.4)*0.15;
    }
  }
  const n=src.length, act=aS/n, inh=iS/n, crs=cross/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.07-ang*2+t*0.9))*0.3;
  const micro=Math.sin(sx*0.3+sy*0.2+t*3)*Math.sin(sx*0.2-sy*0.3-t*2.5)*0.15;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+crs*0.8+micro)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const edge=Math.abs(reaction)>0.65?1.0:0.0;
  const glow=Math.exp(-Math.abs(reaction)*3)*0.4;
  const blend=reaction*0.65+cell*0.2+edge*0.1+glow*0.05;
  const v=blend*0.5+0.5;
  const pal=[
    [5,12,52],[12,45,95],[18,85,120],[25,135,130],
    [60,170,145],[140,190,100],[210,195,60],
    [225,145,55],[215,90,60],[180,50,70],[110,25,65],[50,15,55],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const hi=edge?1.2:glow>0.1?1.1:1.0;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*hi)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*hi)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*hi)|0
  ];
}
